example.source:
deepml vfx 0.3
module corpus.deepml_vfx.example_02251
policy deterministic
policy no_network
effect Effect02251 {
  fluid Smoke { grid: [75,75,59] solver: stable_fluids }
  cloth Banner { resolution: [27,27] stiffness: 0.6 }
  destruction Debris { pieces: 19 fracture: voronoi seed: 2251 }
  collision_field WorldSDF source scene.Collider
  volumetric Fog { density: 0.4 }
  shader function ShadePortal(x: vec3) -> color
  render_target FXColor format rgba16f
  mask PortalMask source scene.PortalA
}
assert render_hash == "invalid-02251"

